package dev.mineagent.runtime.core.interaction;
import com.fasterxml.jackson.databind.*;import dev.mineagent.runtime.core.creature.CreatureAnimation;import java.util.*;
/** Whole-model and local ModelPart tracks. Native geometry/textures remain owned by their renderer. */
public record EntityAnimationSpec(EntitySelector selector,boolean blockNative,boolean additive,CreatureAnimation.Clip root,Map<String,CreatureAnimation.Clip> parts,String source){
 public static EntityAnimationSpec parse(String source){try{if(source==null||source.length()>14000)throw new IllegalArgumentException("ENTITY_ANIMATION_SIZE");var json=new ObjectMapper(com.fasterxml.jackson.core.JsonFactory.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).build()).enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);var j=json.readTree(source);EntityLogicSpec.keys(j,"dimension","entity_id","entity_type","species_id","part_index","name","block_native","mode","duration_ticks","loop","root","parts");var selector=EntitySelector.parse(j);String mode=j.path("mode").asText("add");if(!Set.of("add","replace").contains(mode))throw new IllegalArgumentException("ENTITY_ANIMATION_MODE");for(String k:List.of("block_native","loop"))if(j.has(k)&&!j.get(k).isBoolean())throw new IllegalArgumentException("ENTITY_ANIMATION_BOOLEAN");var parts=new LinkedHashMap<String,CreatureAnimation.Clip>();if(j.has("parts")){if(!j.get("parts").isObject()||j.get("parts").size()>128)throw new IllegalArgumentException("ENTITY_ANIMATION_PARTS");for(var e:j.get("parts").properties()){if((e.getKey().isBlank()||e.getKey().length()>180||e.getKey().chars().anyMatch(Character::isISOControl)))throw new IllegalArgumentException("ENTITY_ANIMATION_PART_PATH");parts.put(e.getKey(),clip(json,j,e.getValue(),true));}}return new EntityAnimationSpec(selector,j.path("block_native").asBoolean(false),mode.equals("add"),j.has("root")?clip(json,j,j.get("root"),false):null,Map.copyOf(parts),json.writeValueAsString(j));}catch(IllegalArgumentException e){throw e;}catch(Exception e){throw new IllegalArgumentException("ENTITY_ANIMATION_INVALID",e);}}
 private static CreatureAnimation.Clip clip(ObjectMapper json,JsonNode j,JsonNode frames,boolean part){if(part){frames=frames.deepCopy();if(frames.isArray())for(var frame:frames)if(frame.path("translation").isArray()){var values=(com.fasterxml.jackson.databind.node.ArrayNode)frame.get("translation");for(int i=0;i<values.size();i++)if(values.get(i).isNumber())values.set(i,json.getNodeFactory().numberNode(values.get(i).asDouble()/16));}}var wrapper=json.createObjectNode();var c=wrapper.putObject("idle");c.put("duration_ticks",EntityLogicSpec.integer(j,"duration_ticks",40,1,72000));c.put("loop",j.path("loop").asBoolean(true));c.set("keyframes",frames);return CreatureAnimation.parse(wrapper).get("idle");}
}
